import{_ as r,o,c as e,a2 as s}from"./chunks/framework.BWuWLRhz.js";const _=JSON.parse('{"title":"搜尋歷程記錄","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/settings/history.md","filePath":"zh-TW/user-guide/settings/history.md","lastUpdated":1787586465000}'),n={name:"zh-TW/user-guide/settings/history.md"};function a(i,t,l,g,d,c){return o(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="搜尋歷程記錄" tabindex="-1">搜尋歷程記錄 <a class="header-anchor" href="#搜尋歷程記錄" aria-label="Permalink to &quot;搜尋歷程記錄&quot;">​</a></h1><p>搜尋歷程記錄頁面用於管理 Lertaro 的使用痕跡與智慧推薦權重。頁面頂部包含兩個相互獨立的索引標籤頁：<strong>搜尋歷程</strong>與<strong>關鍵字歷程</strong>。</p><h2 id="_1-搜尋歷程-search-history" tabindex="-1">1. 搜尋歷程（Search History） <a class="header-anchor" href="#_1-搜尋歷程-search-history" aria-label="Permalink to &quot;1. 搜尋歷程（Search History）&quot;">​</a></h2><p>搜尋歷程追蹤你實際點擊或按 Enter 開啟過的搜尋結果，並將開啟時的「搜尋關鍵字」與「目標實體路徑」進行雙向綁定學習：</p><ul><li><strong>智慧優先召回</strong>：當你之後輸入與先前查詢相似或模糊相關的字元時，Lertaro 會自動在結果清單前列優先召回該檔案。例如，你曾透過輸入 <code>bcomp</code> 開啟過 <code>BCompare.exe</code>，未來只需輸入 <code>bc</code>，該程式依然會被優先推至前排。</li><li><strong>內嵌視窗智慧分區</strong>：在檔案選取對話方塊的內嵌搜尋中，歷程比對項目若屬於目前資料夾內，會自動歸入「目前資料夾」分組，其餘則歸入「全域搜尋」分組。</li><li><strong>失效路徑自動過濾</strong>：若已記錄的檔案或目錄被外部刪除或移動，Lertaro 在檢索時會自動過濾不存在的無效連結，且相同路徑在清單中絕不重複顯示。</li><li><strong>管理操作</strong>： <ul><li><strong>啟用歷程記錄功能</strong>：總開關，關閉後保留現有資料但不再記錄新的開啟行為。</li><li><strong>搜尋過濾</strong>：在上方搜尋框輸入關鍵字快速定位特定歷程項目。</li><li><strong>單筆刪除與一鍵清空</strong>：每行配有刪除按鈕，亦可按一下<strong>清空全部歷程</strong>重設所有開啟記錄。</li></ul></li></ul><h2 id="_2-關鍵字歷程-keyword-history" tabindex="-1">2. 關鍵字歷程（Keyword History） <a class="header-anchor" href="#_2-關鍵字歷程-keyword-history" aria-label="Permalink to &quot;2. 關鍵字歷程（Keyword History）&quot;">​</a></h2><p>關鍵字歷程專門用於記憶你在快速搜尋視窗中鍵入過的<strong>原始查詢字串</strong>（無論是否最終開啟了檔案）：</p><ul><li><strong>快速鍵快速翻閱</strong>：在快速搜尋視窗中，可使用快速鍵 <strong><code>Alt+Up</code></strong> 向前翻閱、<strong><code>Alt+Down</code></strong> 向後翻閱最近輸入過的搜尋詞；按下 <strong><code>Ctrl+Delete</code></strong> 即可從歷程中直接刪除目前顯示的這條詞彙。</li><li><strong>獨立控制與維護</strong>：與搜尋歷程一樣提供專屬的<strong>啟用歷程記錄功能</strong>開關、關鍵字搜尋過濾、單筆刪除與<strong>清空全部歷程</strong>按鈕。</li></ul>',8)])])}const u=r(n,[["render",a]]);export{_ as __pageData,u as default};
